    if len(xs) == 1:
        return xs

    less, equal, greater = [], [], []  # Divide

    pivot = xs[index]


    for x in xs:
        if x < pivot:
            less.append(x)
        elif x == pivot:
            equal.append(x)
        else:
            greater.append(x)

    if index < len(less):
        return quickselect_quote(less, index)  
    elif index < len(less) + len(equal):
        return pivot
    else:
        return quickselect_quote(greater, index - len(less) - len(equal)) 
